WITH ref AS (SELECT data_referencia FROM param LIMIT 1), w6 AS (SELECT DATE(ref.data_referencia, '-6 months') dt FROM ref), w12 AS (SELECT DATE(ref.data_referencia, '-12 months') dt FROM ref)CREATE TABLE mart_lista_nominal_hipertensao STRICT (  co_fat_cidadao_pec INTEGER PRIMARY KEY,  no_cidadao TEXT,  nu_cns TEXT NOT NULL,  nu_cpf_cidadao TEXT NOT NULL,  dt_nascimento TEXT NOT NULL,  idade INTEGER,  ds_sexo TEXT NOT NULL,  nu_ine TEXT NOT NULL,  no_equipe TEXT NOT NULL,  nu_microarea TEXT,  -- Sempre NULL: sem fonte  nu_telefone_celular TEXT NOT NULL,  consulta_status TEXT NOT NULL,  consulta_dt_ultima TEXT,  pa_status TEXT NOT NULL,  pa_dt_ultima TEXT,  pa_sistolica INTEGER,  pa_diastolica INTEGER,  peso_altura_status TEXT NOT NULL,  peso_altura_dt_ultima TEXT,  qt_praticas_pendentes INTEGER NOT NULL,  data_referencia TEXT NOT NULL) WITHOUT ROWID;INSERT INTO mart_lista_nominal_hipertensaoSELECT  c.co_fat_cidadao_pec,  CASE WHEN TRIM(c.no_cidadao) = '' THEN NULL ELSE TRIM(c.no_cidadao) END no_cidadao,  c.nu_cns,  c.nu_cpf_cidadao,  c.dt_registro_nascimento,  -- Idade: nula se nascimento > data_referencia  CASE    WHEN c.dt_registro_nascimento > (SELECT data_referencia FROM ref)    THEN NULL    ELSE CAST(      JULIANDAY(CAST((SELECT data_referencia FROM ref) AS TEXT)) -      JULIANDAY(c.dt_registro_nascimento)    ) / 365.25 AS INTEGER)  END idade,  c.ds_sexo,  c.nu_ine,  c.no_equipe,  NULL nu_microarea,  -- FR-023: sem fonte  c.nu_telefone_celular,  -- Consulta: status  CASE    WHEN uc.dt_ultima IS NULL THEN 'NUNCA_REALIZADA'    WHEN uc.dt_ultima >= (SELECT dt FROM w6) THEN 'EM_DIA'    ELSE 'ATRASADA'  END consulta_status,  uc.dt_ultima consulta_dt_ultima,  -- Aferição PA: status  CASE    WHEN upa.dt_ultima IS NULL THEN 'NUNCA_REALIZADA'    WHEN upa.dt_ultima >= (SELECT dt FROM w6) THEN 'EM_DIA'    ELSE 'ATRASADA'  END pa_status,  upa.dt_ultima pa_dt_ultima,  upa.pa_sistolica,  upa.pa_diastolica,  -- Peso + Altura: status  CASE    WHEN upz.dt_ultima IS NULL THEN 'NUNCA_REALIZADA'    WHEN upz.dt_ultima >= (SELECT dt FROM w12) THEN 'EM_DIA'    ELSE 'ATRASADA'  END peso_altura_status,  upz.dt_ultima peso_altura_dt_ultima,  -- Quantas práticas não estão EM_DIA  (CASE WHEN CASE WHEN uc.dt_ultima IS NULL THEN 'NUNCA_REALIZADA' WHEN uc.dt_ultima >= (SELECT dt FROM w6) THEN 'EM_DIA' ELSE 'ATRASADA' END <> 'EM_DIA' THEN 1 ELSE 0 END)  + (CASE WHEN CASE WHEN upa.dt_ultima IS NULL THEN 'NUNCA_REALIZADA' WHEN upa.dt_ultima >= (SELECT dt FROM w6) THEN 'EM_DIA' ELSE 'ATRASADA' END <> 'EM_DIA' THEN 1 ELSE 0 END)  + (CASE WHEN CASE WHEN upz.dt_ultima IS NULL THEN 'NUNCA_REALIZADA' WHEN upz.dt_ultima >= (SELECT dt FROM w12) THEN 'EM_DIA' ELSE 'ATRASADA' END <> 'EM_DIA' THEN 1 ELSE 0 END)  qt_praticas_pendentes,  (SELECT data_referencia FROM ref) data_referenciaFROM int_coorte_hipertensao crtJOIN stg_cidadao c ON crt.co_fat_cidadao_pec = c.co_fat_cidadao_pecLEFT JOIN int_ultima_consulta uc ON c.co_fat_cidadao_pec = uc.co_fat_cidadao_pecLEFT JOIN int_ultima_afericao_pa upa ON c.co_fat_cidadao_pec = upa.co_fat_cidadao_pecLEFT JOIN int_ultimo_peso_altura upz ON c.co_fat_cidadao_pec = upz.co_fat_cidadao_pec;CREATE INDEX idx_mart_status_consulta ON mart_lista_nominal_hipertensao(consulta_status);CREATE INDEX idx_mart_status_pa ON mart_lista_nominal_hipertensao(pa_status);CREATE INDEX idx_mart_status_pz ON mart_lista_nominal_hipertensao(peso_altura_status);CREATE INDEX idx_mart_qty_pendentes ON mart_lista_nominal_hipertensao(qt_praticas_pendentes);